import discord
from discord.ext import commands
import asyncio
import random
from discord.ui import Button,View,Select

intents=discord.Intents.default()
intents.message_content=True
bot=commands.Bot(command_prefix = 'a.',intents = intents,help_command=None)
@bot.event
async def on_ready():
    print(f'Eda mone {bot.user}')
@bot.event
async def on_ready():
    guild_count = len(bot.guilds)
    await bot.change_presence(activity=discord.Game(name=f"on {guild_count} servers"))
    print(f"Bot is ready and running on {guild_count} servers.")


@bot.event
async def on_message(message):
    # Prevent bot from replying to itself
    if message.author == bot.user:
        return

    # Check if bot was mentioned
    if bot.user in message.mentions:
        await message.channel.send(f"Hello {message.author.mention}, you mentioned me! Use a.help to learn more about the bot")

    # Make sure commands still work
    await bot.process_commands(message)


# Dropdown menu handler
class EmbedDropdown(discord.ui.Select):
    def __init__(self):
        options = [
            discord.SelectOption(label="🏏 Play Cricket Match", description="Play matches with custom teams or prebuilt teams", value="overview"),
            discord.SelectOption(label="📊 Test Match Simulation", description="3 Different playing modes", value="simulation"),
            discord.SelectOption(label="🎬 Credits", description="Who built this?", value="credits")
        ]

        super().__init__(placeholder="Choose a section...", options=options)

    async def callback(self, interaction: discord.Interaction):
        # Embed options based on selection
        if self.values[0] == "overview":
            embed = discord.Embed(
                title="🏏 Play Match",
                
                description="Play against your friends/bot in the match mode. There is a custom and prebuilt teams mode. Make strategic choices and set fields with 25+ possible fielding positions. Use the a.cplay for singleplayer and a.cplay @opponent for multiplayer mode.",
                
                color=discord.Color.from_rgb(217, 245, 7)
            )
            embed.set_footer(text="Match Page"),
            embed.set_thumbnail(url="https://media.discordapp.net/attachments/1394982758060916797/1395673909520629861/5ad40e05-e8cb-4b5c-a831-4cb389f0f56e.png?ex=687b4e1e&is=6879fc9e&hm=751ebbde74277f5146e113d4dc6387e19d9e75ffdb6ac9f95b87eba8180eb06f&=&format=webp&quality=lossless&width=930&height=930"),
            embed.set_image(url="https://media.discordapp.net/attachments/1394416108949340173/1395683080693485608/image.png?ex=687b56a8&is=687a0528&hm=b45269347c98e2c22512c1d58af95860fdf4574f72252678c7eb952ab34927d9&=&format=webp&quality=lossless&width=930&height=914"),
        elif self.values[0] == "simulation":
            embed = discord.Embed(
                title="📊 Test Match Simulation",
                description="This simulator can be played in 3 modes, a one-off, series or tournament mode. The tournament mode can be won by beating 8 All-Star teams from different countries. Use a.sim to play.",
                color=discord.Color.green()
            )
            embed.set_thumbnail(url="https://media.discordapp.net/attachments/1394982758060916797/1395673909520629861/5ad40e05-e8cb-4b5c-a831-4cb389f0f56e.png?ex=687b4e1e&is=6879fc9e&hm=751ebbde74277f5146e113d4dc6387e19d9e75ffdb6ac9f95b87eba8180eb06f&=&format=webp&quality=lossless&width=930&height=930"),
            embed.set_image(url="https://media.discordapp.net/attachments/1394416108949340173/1395686421464875110/image.png?ex=687b59c5&is=687a0845&hm=27757bdd3841bb3beac9f7c46c0abcb3efc47b3c5aab23392e21877f24f945eb&=&format=webp&quality=lossless&width=1109&height=900")
            embed.set_footer(text="Scorecard Page")

        elif self.values[0] == "credits":
            embed = discord.Embed(
                title="🎬 Credits",
                description="This is my first discord bot, for any queries reach out to me (<@771079399897956352>). Please support me to reach on top.gg",
                color=discord.Color.purple()
            )
            embed.set_image(url="https://media.discordapp.net/attachments/1394982758060916797/1395673909520629861/5ad40e05-e8cb-4b5c-a831-4cb389f0f56e.png?ex=687b4e1e&is=6879fc9e&hm=751ebbde74277f5146e113d4dc6387e19d9e75ffdb6ac9f95b87eba8180eb06f&=&format=webp&quality=lossless&width=930&height=930"),
            embed.set_thumbnail(url="https://media.discordapp.net/attachments/1394982758060916797/1395673909520629861/5ad40e05-e8cb-4b5c-a831-4cb389f0f56e.png?ex=687b4e1e&is=6879fc9e&hm=751ebbde74277f5146e113d4dc6387e19d9e75ffdb6ac9f95b87eba8180eb06f&=&format=webp&quality=lossless&width=930&height=930"),
            embed.set_footer(text="Credits Page")

        await interaction.response.edit_message(embed=embed, view=self.view)

