matches = {}  # {guild_id: {"players": [], "started": False, "host": None, "order": [], "turn_index": 0, "game_running": False}}

@bot.command()
async def atlasc(ctx):
    guild_id = ctx.guild.id
    if guild_id in matches and matches[guild_id]["started"]:
        await ctx.send("A match is already in progress!")
        return

    matches[guild_id] = {
        "players": [ctx.author],
        "started": True,
        "host": ctx.author,
        "order": [],
        "turn_index": 0,
        "game_running": False
    }
    await ctx.send(f"{ctx.author.mention} has started an Atlas match! Type `a.join` to participate!")

@bot.command()
async def playersc(ctx):
    guild_id = ctx.guild.id
    if guild_id not in matches or not matches[guild_id]["started"]:
        await ctx.send("No active match.")
        return
    
    player_names = [p.display_name for p in matches[guild_id]["players"]]
    await ctx.send(f"Current players: {', '.join(player_names)}")

@bot.command()
async def joinc(ctx):
    guild_id = ctx.guild.id
    if guild_id not in matches or not matches[guild_id]["started"]:
        await ctx.send("No Atlas match is currently running. Type `!atlas` to start one!")
        return

    if matches[guild_id]["game_running"]:
        await ctx.send("The game has already started, you can't join now!")
        return

    if ctx.author in matches[guild_id]["players"]:
        await ctx.send(f"{ctx.author.mention}, you are already in the match!")
        return

    matches[guild_id]["players"].append(ctx.author)
    await ctx.send(f"{ctx.author.mention} has joined the match!")

@bot.command()
async def startc(ctx):
    guild_id = ctx.guild.id
    if guild_id not in matches or not matches[guild_id]["started"]:
        await ctx.send("No match is currently running.")
        return

    if ctx.author != matches[guild_id]["host"]:
        await ctx.send(f"Only {matches[guild_id]['host'].mention} can start the game!")
        return

    if len(matches[guild_id]["players"]) < 2:
        await ctx.send("Need at least 2 players to start the game.")
        return

    matches[guild_id]["order"] = matches[guild_id]["players"][:]
    random.shuffle(matches[guild_id]["order"])
    matches[guild_id]["game_running"] = True
    matches[guild_id]["turn_index"] = 0

    order_names = [p.display_name for p in matches[guild_id]["order"]]
    await ctx.send(f"Game started! Player order: {', '.join(order_names)}")

    await run_game(ctx, guild_id)

async def update_timer(msg, end_time, player, letter, stop_event):
    while not stop_event.is_set():
        time_left = int(end_time - asyncio.get_event_loop().time())
        if time_left < 0:
            break
        await msg.edit(content=f"It's {player.mention}'s turn! Start with **{letter.upper()}**. Time left: {time_left}s")
        await asyncio.sleep(1)

