        async def tutorial(ctx):
            import matplotlib.pyplot as plt
            import tempfile
            import os
            import numpy as np
            mapa={}
            mapping={'1st Slip':'slip1','2nd Slip':'slip2','3rd Slip':'slip3','4th Slip':'slip4','Fine Leg':'fineleg','Third Man':'thirdman','Short Third Man':'shortthirdman','Long Leg':'longleg',
                'Square Leg':'squareleg','Deep Square Leg':'deepsquareleg','Mid Wicket':'midwicket','Deep Mid Wicket':'deepmidwicket','Mid On':'midon','Mid Off':'midoff','Long On':'longon',
                'Long Off':'longoff','Covers':'covers','Deep Covers':'deepcovers','Point':'point','Deep Point':'deeppoint','Deep Fine Leg':'deepfineleg','Backward Point':'backwardpoint','Backward Square Leg':'backwardsquareleg','Cow Corner':'cowcorner','Deep Extra Covers':'deepextracovers','Deep Cover Point':'deepcoverpoint','Cover Point':'coverpoint'}
            for i in mapping:
                mapa[mapping[i]]=i
            field_position = {
                "midon": (300,30),
                "slip2": (115, 22),
                "slip3": (120, 22),
                "slip4": (130, 22),

                "longleg": (0, 30),
                "backwardsquareleg": (44, 30),
                "deepfineleg": (65, 65),
                "fineleg": (65, 30),
                "longleg": (50, 65),
                "deepmidwicket": (350,66),

                "squareleg": (20, 30),
                "thirdman": (105, 65),
                "deepsquareleg": (12, 65),

                "midwicket": (345, 30),
                "shortthirdman": (110, 30),
                "cowcorner": (330, 65),

                "slip1": (105, 22),
                "longon": (292, 66),
                "midoff": (240, 30),
                "longoff": (250, 65),

                "covers": (195, 30),
                "deepcovers": (210, 68),
                "coverpoint": (180, 30),
                "deepcoverpoint": (180, 68),

                "point": (160, 30),
                "deeppoint": (170, 66),
                "backwardpoint": (140, 30),

                "deepextracovers": (193, 68)
            }
            catchers={}
            g={}

            fig, ax = plt.subplots(figsize=(6, 6))
            ax.set_xlim(-75, 75)
            ax.set_ylim(-75, 75)

            # Draw field boundary
            field = plt.Circle((0, 0), 70, color='green', ec='black')
            ax.add_patch(field)
            pitch_width = 4
            pitch_length = 26
            pitch = plt.Rectangle((-pitch_width / 2, -pitch_length / 2), pitch_width, pitch_length,color='saddlebrown', ec='black')
            ax.add_patch(pitch)
            # Plot fielder positions
            for pos, (angle_deg, radius) in field_position.items():
                angle_rad = angle_deg * 3.14 / 180
                x = radius * np.cos(angle_rad)
                y = radius * np.sin(angle_rad)
                ax.plot(x, y, 'ro')  # red dot
                ax.text(x - 3, y + 3, mapa[pos], fontsize=8)
            
            plt.title('Field for Right Handers')
            ax.set_aspect('equal')
            ax.axis('off')
            plt.tight_layout()
            with tempfile.NamedTemporaryFile(delete=False, suffix=".png") as tmpfile:
                plt.savefig(tmpfile.name,bbox_inches="tight", pad_inches=0.5)
                tmpfile_path = tmpfile.name

            plt.close()

            # 3. Send the file
            await ctx.send(file=discord.File(tmpfile_path))

            # 4. Cleanup
            os.remove(tmpfile_path)
            # Define standard positions in polar coordinates (radians, radius)
            
            

            fig, ax = plt.subplots(figsize=(6, 6))
            ax.set_xlim(-75, 75)
            ax.set_ylim(-75, 75)

            # Draw field boundary
            field = plt.Circle((0, 0), 70, color='green', ec='black')
            ax.add_patch(field)
            pitch_width = 4
            pitch_length = 26
            pitch = plt.Rectangle((-pitch_width / 2, -pitch_length / 2), pitch_width, pitch_length,
                                color='saddlebrown', ec='black')
            ax.add_patch(pitch)
            # Plot fielder positions
            for pos, (angle_deg, radius) in field_position.items():
                angle_rad = -angle_deg * 3.14 / 180
                x = -radius * np.cos(angle_rad)
                y = -radius * np.sin(angle_rad)
                ax.plot(x, y, 'ro')  # red dot
                ax.text(x - 3, y + 3, pos, fontsize=8)
            
            plt.title("Field for Left Handers")
            plt.tight_layout()
            ax.set_aspect('equal')
            ax.axis('off')
            with tempfile.NamedTemporaryFile(delete=False, suffix=".png") as tmpfile:
                plt.savefig(tmpfile.name,bbox_inches="tight", pad_inches=0.5)
                tmpfile_path = tmpfile.name

            plt.close()

            # 3. Send the file
            await ctx.send(file=discord.File(tmpfile_path))

            # 4. Cleanup
            os.remove(tmpfile_path)
        
