        import json
        import os

        # Load entire progress file
        def load_progress(filename):
            if not os.path.exists(filename):
                return {}  # If file doesn't exist, return empty dict

            with open(filename, "r") as f:
                try:
                    return json.load(f)  # Returns a dict with user IDs as keys
                except json.JSONDecodeError:
                    return {}

        # Check if the user has progress saved
        def user_has_progress(user_id):
            progress = load_progress(filename)
            return str(user_id) in progress  # Convert ID to string to match JSON keys
