        class Deliverydropdown(Select):
            def __init__(self, allowed_user:discord.User):
                self.allowed_user = allowed_user

                # Build dropdown options
                options = []
                for i in range(len(LKI)):
                    if mapping[LKI[i]] not in Pxi:
                        options.append(discord.SelectOption(label=LKI[i],description=f'Bat: {batrat[mapping[LKI[i]]]}  Bowl: {bowlrat[mapping[LKI[i]]]}'))

                # Limit to max 25 options
                options = options[:25]

                # Initialize Select properly
                super().__init__(
                    placeholder="Choose player...",
                    min_values=1,
                    max_values=1,
                    options=options
                )

            async def callback(self, interaction: discord.Interaction):
                if interaction.user.id != self.allowed_user.id:
                    await interaction.response.send_message("🚫 You’re not allowed to select.", ephemeral=True)
                    return
                
                self.view.selected = self.values[0]
                self.view.stop()


