                    line = "+---------------+----+----+----+----+----+---------+"
                    table = [title, line]
                    table.append("| {:<13} | {:<2} | {:<2} | {:<2} | {:<2} | {:<3} | {:<6} |".format(*headers))
                    table.append(line)

                    for row in data:
                        team, p, w, l, t, pts, nrr = row
                        table.append("| {:<13} | {:>2} | {:>2} | {:>2} | {:>2} | {:>3} | {:>6} |".format(team, p, w, l, t, pts, f"{nrr:.2f}"))

                    table.append(line)
                    return "```\n" + "\n".join(table) + "\n```"

