                def format_table(data, c):
                    title = f"Indian Premier League 2023 Points Table [After Game {c} of 70]\n"
                    headers = ["Team", "P", "W", "L", "T", "Pts", "NRR"]
                    line = "+--------------------------------+----+----+----+----+----+---------+"
                    table = [title, line]
                    table.append("| {:<30} | {:<2} | {:<2} | {:<2} | {:<2} | {:<3} | {:<6} |".format(*headers))
                    table.append(line)

                    for row in data:
                        team, p, w, l, t, pts, nrr = row
                        table.append("| {:<30} | {:>2} | {:>2} | {:>2} | {:>2} | {:>3} | {:>6} |".format(team, p, w, l, t, pts, f"{nrr:.2f}"))

                    table.append(line)
                    return "```\n" + "\n".join(table) + "\n```"

                table_text = format_table(table,cow)
                await ctx.send(table_text)
                        
